import React, { useEffect, useState } from "react";
import "./../css/bot.css";
import DatePicker from 'react-datepicker';
import 'react-datepicker/dist/react-datepicker.css';
import TimePicker from 'react-time-picker';

function Home() {
  useEffect(() => {
    const chatForm = document.getElementById("chat-form");
    const chatInput = document.getElementById("chat-input");
    const chatLogs = document.querySelector(".chat-logs");

    const handleSubmit = async (event) => {
      event.preventDefault();

      const userPrompt = chatInput.value.trim();

      if (!userPrompt) {
        return; // Don't proceed if the input is empty
      }

      // Display user message in the chat log
      displayUserMessage(userPrompt);

      try {
        // Call the Flask API chatbot
        const response = await fetch("http://localhost:5001/chatbot", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ user_prompt: userPrompt }),
        });

        if (response.ok) {
          const data = await response.json();
          // Display bot's response in the chat log
          displayBotResponse(data.response);
        } else {
          console.error("Error fetching response from API");
        }
      } catch (error) {
        console.error("Error:", error);
      }

      // Clear the input
      chatInput.value = "";
    };

    const displayUserMessage = (message) => {
      const chatLog = document.createElement("div");
      chatLog.className = "chat-msg user";
      chatLog.innerHTML = `<div class="cm-msg-text">${message}</div>`;
      chatLogs.appendChild(chatLog);
    };

    const displayBotResponse = (response) => {
      const chatLog = document.createElement("div");
      chatLog.className = "chat-msg self";
      chatLog.innerHTML = `<div class="cm-msg-text">${response}</div>`;
      chatLogs.appendChild(chatLog);
    };


    chatForm.addEventListener("submit", handleSubmit);

    // Cleanup function
    return () => {
      chatForm.removeEventListener("submit", handleSubmit);
    };
  }, []); // Empty dependency array for componentDidMount behavior




  const [searchTerm, setSearchTerm] = useState("");
  const [searchResults, setSearchResults] = useState([]);
  const [selectedService, setSelectedService] = useState(null);
  const [userLocation, setUserLocation] = useState(null);
  const [searchResultsTable, setSearchResultsTable] = useState([]);

  const handleInputChange = (e) => {
    const searchTerm = e.target.value;
    setSearchTerm(searchTerm);

    if (searchTerm.trim() === "") {
      setSearchResults([]);
    } else {
      const results = services
        .filter((service) =>
          service.hsServices.toLowerCase().includes(searchTerm.toLowerCase())
        )
        .reduce((uniqueResults, service) => {
          // Check if the service is already in uniqueResults
          if (
            !uniqueResults.some(
              (result) => result.hsServices === service.hsServices
            )
          ) {
            // If not, add it to uniqueResults
            uniqueResults.push(service);
          }
          return uniqueResults;
        }, []);

      setSearchResults(results);
    }
  };

  const handleServiceSelect = (selectedService) => {
    setSelectedService(selectedService);
    setSearchTerm(selectedService.hsServices); // Populate search bar
    setSearchResults([]); // Clear search results
  };

  const handleSearch = async () => {
    if (selectedService && userLocation) {
      try {
        // Reset previous info apart from user latitude and longitude
        setSelectedService(null);
        setSearchResults([]);
        setSearchResultsTable([]);

        const response = await fetch(
          "http://localhost:5206/api/HospitalServices/Search",
          {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify({
              userLatitude: userLocation.latitude,
              userLongitude: userLocation.longitude,
              service: selectedService.hsServices,
            }),
          }
        );

        if (response.ok) {
          const data = await response.json();
          // Handle the response data as needed
          console.log("Nearest Hospital:", data);
          setSearchResultsTable(data);
        } else {
          console.error("Error fetching nearest hospital from API");
          // Show an error message
          setSearchResultsTable([]);
          setSearchResults([{ hsServices: "Error fetching data" }]);
        }
      } catch (error) {
        console.error("Error:", error);
      }
    }
  };



  const SearchResultList = ({ results }) => (
    <ul className="list-group list-group-flush">
      {results.map((service, index) => (
        <li
          className="list-group-item"
          key={index}
          onClick={() => handleServiceSelect(service)}
        >
          {service.hsServices}
        </li>
      ))}
    </ul>
  );

  //call services api

  const [services, setServices] = useState([]);

  useEffect(() => {
    const fetchServices = async () => {
      try {
        const response = await fetch(
          "http://localhost:5206/api/HospitalServices"
        );

        if (response.ok) {
          const data = await response.json();
          setServices(data); // Assuming the API response is an array of services
        } else {
          console.error("Error fetching services from API");
        }
      } catch (error) {
        console.error("Error:", error);
      }
    };

    fetchServices();
  }, []);


  const SearchResultsTable = ({ results }) => (
    <div className="row mt-3">
      {results.map((result, index) => (
        <div key={index} className="col-lg-6 col-md-6">
          <div className="service-item bg-light rounded d-flex flex-column align-items-center justify-content-center text-center">
            <div className="service-icon mb-4">
              <i className="fa fa-2x fa-user-md text-white" />
            </div>
            <h3 className="mb-3">{result.hName}</h3>
            <h5 className="m-0">{result.hAddress}</h5><br />
            <h4 className="m-0" style={{color:'red'}}>Distance: {result.distanceInKm.toFixed(2)} km</h4>

          </div>
        </div>
      ))}
    </div>
  );
  /// end services api


  useEffect(() => {
    const fetchLocation = async () => {
      try {
        const position = await getCurrentLocation();
        setUserLocation(position.coords);
      } catch (error) {
        console.error("Error getting user location:", error);
      }
    };

    fetchLocation();
  }, []);

  const getCurrentLocation = () => {
    return new Promise((resolve, reject) => {
      if ("geolocation" in navigator) {
        navigator.geolocation.getCurrentPosition(resolve, reject);
      } else {
        reject("Geolocation not available");
      }
    });
  };




    const [doctors, setDoctors] = useState([]);

    useEffect(() => {
      const fetchDoctors = async () => {
        try {
          const response = await fetch("http://localhost:5206/api/Doctors_Cr");

          if (response.ok) {
            const data = await response.json();
            setDoctors(data);
          } else {
            console.error("Error fetching doctors from API");
          }
        } catch (error) {
          console.error("Error:", error);
        }
      };

      fetchDoctors();
    }, []);

    const getOneDoctorPerHospital = () => {
      const uniqueHospitals = new Set();
      const doctorsPerHospital = [];

      doctors.forEach((doctor) => {
        if (!uniqueHospitals.has(doctor.dhId)) {
          uniqueHospitals.add(doctor.dhId);
          doctorsPerHospital.push(doctor);
        }
      });

      return doctorsPerHospital;
    };

    const doctorsList = getOneDoctorPerHospital();




    //doctors appointment

    const [dobPickerOpen, setDobPickerOpen] = useState(false);
    const [apptDatePickerOpen, setApptDatePickerOpen] = useState(false);


    const handleDOBChange = (date) => {
      setFormData((prevFormData) => ({ ...prevFormData, APatientDOB: date }));
      setDobPickerOpen(false);
    };

    const handleApptDateChange = (date) => {
      setFormData((prevFormData) => ({ ...prevFormData, ADate: date }));
      setApptDatePickerOpen(false);
    };

      const [formData, setFormData] = useState({
        APatientName: "",
        APatientDOB: "",
        ADate: "",
        ATime: "",
        ADId: "",
        AType: "",
        AMobile: "",
        AEmail: "",
        AReason: "",
      });

      const [doctorsA, setDoctorsA] = useState([]);
      const [hospitals, setHospitals] = useState([]);
      const [loading, setLoading] = useState(false);

      const fetchDoctorsA = async (dhId) => {
        try {
          const response = await fetch(`http://localhost:5206/api/Doctors_Cr/ByHospitalId/${dhId}`);
          if (response.ok) {
            const doctorList = await response.json();
            setDoctors(doctorList);
          } else {
            console.error("Failed to fetch doctors:", response.status, response.statusText);
          }
        } catch (error) {
          console.error("An error occurred while fetching doctors:", error);
        }
      };

      useEffect(() => {
        const fetchHospitalsA = async () => {
          try {
            const response = await fetch("http://localhost:5206/api/Hospital_Cr");
            if (response.ok) {
              const hospitalList = await response.json();
              setHospitals(hospitalList);
            } else {
              console.error("Failed to fetch hospitals:", response.status, response.statusText);
            }
          } catch (error) {
            console.error("An error occurred while fetching hospitals:", error);
          }
        };

        fetchHospitalsA();
      }, []);

      const handleSubmitA = async (e) => {
        e.preventDefault();
        console.log("Form submitted");

        try {
          setLoading(true);
          console.log("Form Data:", formData); // Log the form data for debugging

          const response = await fetch("http://localhost:5206/api/appointment_cr", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify(formData),
          });

          if (response.ok) {
            setFormData({
              APatientName: "",
              APatientDOB: "",
              ADate: "",
              ATime: "",
              ADId: "",
              AType: "",
              AMobile: "",
              AEmail: "",
              AReason: "",
            });
            setLoading(false);

            // Add any additional actions you want to perform after successful submission
          } else {
            console.error("Failed to create appointment:", response.status, response.statusText);
          }
        } catch (error) {
          console.error("An error occurred during form submission:", error);
          setLoading(false);
        }
      };

      const handleInputChangeA = (e) => {
        const { name, value } = e.target;
        setFormData((prevFormData) => ({ ...prevFormData, [name]: value }));

        // If the selected input is the hospital dropdown, clear the doctors list and fetch doctors based on the selected hospital
        if (name === "ADhId") {
          setDoctors([]); // Clear the existing doctors list
          fetchDoctorsA(value);
        }
      };


    /// appountment end



  return (
    <div>
      <div>
        <div id="body">
          <div id="chat-circle" className="btn btn-raised">
            <img
              id="chat-bot"
              src="./assets/img/chatbot.png"
              style={{ objectFit: "contain" }}
            />
          </div>
          <div className="chat-box">
            <div className="chat-box-header">
              ChatBot
              <span className="chat-box-toggle">
                <i className="material-icons">close</i>
              </span>
            </div>
            <div className="chat-box-body chatP">
              <div className="chat-box-overlay" />
              <div className="chat-logs" />
            </div>
            <div className="chat-input">
              <form id="chat-form">
                <input
                  type="text"
                  id="chat-input"
                  name="chat-input"
                  placeholder="Send a message..."
                />
                <button type="submit" className="chat-submit">
                  <i className="material-icons">Send</i>
                </button>
              </form>
            </div>
          </div>
        </div>
      </div>




      <div className="container-fluid bg-primary py-5 mb-5 hero-header">
        <div className="container py-5">
          <div className="row justify-content-start">
            <div className="col-lg-8 text-center text-lg-start">
              <h5
                className="d-inline-block text-primary text-uppercase border-bottom border-5"
                style={{ borderColor: "rgba(256, 256, 256, .3) !important" }}
              >
                Welcome To LifeLine
              </h5>
              <h1 className="display-1 text-white mb-md-4">
                Best Healthcare Solution In Your City
              </h1>
              <div className="pt-2">
              </div>
            </div>
          </div>
        </div>
      </div>
      <div>
        <div className="container-fluid py-5">
          <div className="container">
            <div className="row gx-5">
              <div className="col-lg-5 mb-5 mb-lg-0" style={{ minHeight: 500 }}>
                <div className="position-relative h-100">
                  <img
                    className="position-absolute w-100 h-100 rounded"
                    src="./assets/img/about.jpg"
                    style={{ objectFit: "cover" }}
                  />
                </div>
              </div>
              <div className="col-lg-7">
                <div className="mb-4">
                  <h5 className="d-inline-block text-primary text-uppercase border-bottom border-5">
                    About Us
                  </h5>
                  <h1 className="display-4">
                    Best Medical Care For Yourself and Your Family
                  </h1>
                </div>
                <p>
                The foundation of excellent medical care begins with a thorough assessment. This encompasses not only the physical symptoms but also an understanding of the patient's history, lifestyle, and mental well-being. A holistic evaluation allows healthcare providers to tailor treatments that address the individual's unique needs.The best care revolves around the patient. It involves active listening, empathy, and involving the patient in decision-making. When individuals feel heard and respected, it fosters a stronger relationship with their healthcare providers, enhancing the efficacy of treatments and overall satisfaction.
                </p>
                <div className="row g-3 pt-3">
                  <div className="col-sm-3 col-6">
                    <div className="bg-light text-center rounded-circle py-4">
                      <i className="fa fa-3x fa-user-md text-primary mb-3" />
                      <h6 className="mb-0">
                        Qualified
                        <small className="d-block text-primary">Doctors</small>
                      </h6>
                    </div>
                  </div>
                  <div className="col-sm-3 col-6">
                    <div className="bg-light text-center rounded-circle py-4">
                      <i className="fa fa-3x fa-procedures text-primary mb-3" />
                      <h6 className="mb-0">
                        Emergency
                        <small className="d-block text-primary">Services</small>
                      </h6>
                    </div>
                  </div>
                  <div className="col-sm-3 col-6">
                    <div className="bg-light text-center rounded-circle py-4">
                      <i className="fa fa-3x fa-microscope text-primary mb-3" />
                      <h6 className="mb-0">
                        Accurate
                        <small className="d-block text-primary">Testing</small>
                      </h6>
                    </div>
                  </div>
                  <div className="col-sm-3 col-6">
                    <div className="bg-light text-center rounded-circle py-4">
                      <i className="fa fa-3x fa-ambulance text-primary mb-3" />
                      <h6 className="mb-0">
                        Free
                        <small className="d-block text-primary">
                          Ambulance
                        </small>
                      </h6>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>

        <div className="container-fluid py-5">
          <div className="container">
